package net.civeira.phylax.features.document.templateversion.domain;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.document.template.domain.TemplateReference;

class TemplateVersionChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_template_version_change_set_builder() {
    TemplateVersionChangeSet one =
        new TemplateVersionChangeSet().uid("one").template(TemplateReference.of("one"))
            .locale("one").subject("one").contentHtml("one").contentText("one").version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(TemplateReference.of("one"), one.getTemplate().get(),
        "Value must equals to the intial value");
    one.template(TemplateReference.of("two"));
    Assertions.assertEquals(TemplateReference.of("two"), one.getTemplate().get(),
        "Value must equals to the assigned value");
    one.unset("template");
    Assertions.assertFalse(one.getTemplate().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getLocale().get(), "Value must equals to the intial value");
    one.locale("two");
    Assertions.assertEquals("two", one.getLocale().get(),
        "Value must equals to the assigned value");
    one.unset("locale");
    Assertions.assertFalse(one.getLocale().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getSubject().get(), "Value must equals to the intial value");
    one.subject("two");
    Assertions.assertEquals("two", one.getSubject().get(),
        "Value must equals to the assigned value");
    one.unset("subject");
    Assertions.assertFalse(one.getSubject().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getContentHtml().get(),
        "Value must equals to the intial value");
    one.contentHtml("two");
    Assertions.assertEquals("two", one.getContentHtml().get(),
        "Value must equals to the assigned value");
    one.unset("contentHtml");
    Assertions.assertFalse(one.getContentHtml().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getContentText().get(),
        "Value must equals to the intial value");
    one.contentText("two");
    Assertions.assertEquals("two", one.getContentText().get(),
        "Value must equals to the assigned value");
    one.unset("contentText");
    Assertions.assertFalse(one.getContentText().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
